<script setup>
import {computed,ref} from 'vue';
// Read-only: only authorized hrBootstrap records supplied by the hosting workspace.
const props=defineProps({employees:{type:Array,default:()=>[]},records:{type:Object,default:()=>({})},teamLeave:{type:Array,default:()=>[]},role:{type:String,default:'User'}});
const allowed=computed(()=>['Admin','HR'].includes(props.role));
const tab=ref('organization');const company=ref('all');const department=ref('all');const month=ref(new Date().toISOString().slice(0,7));
const companies=computed(()=>props.records.companies||[]), departments=computed(()=>(props.records.departments||[]).filter(x=>company.value==='all'||String(x.companyId)===company.value));
const staff=computed(()=>props.employees.filter(e=>(company.value==='all'||String(e.companyId||e.company||'')===company.value)&&(department.value==='all'||String(e.departmentId||e.department||'')===department.value)));
const names=computed(()=>new Set(staff.value.map(e=>e.name)));
const monthEnd=computed(()=>{const [y,m]=month.value.split('-').map(Number);return new Date(y,m,0).getDate()||31;});
const days=computed(()=>Array.from({length:monthEnd.value},(_,i)=>`${month.value}-${String(i+1).padStart(2,'0')}`));
const leaves=computed(()=>props.teamLeave.filter(x=>names.value.has(x.employee)&&x.start<=`${month.value}-${String(monthEnd.value).padStart(2,'0')}`&&x.end>=`${month.value}-01`));
const namesOfLeaves=computed(()=>[...new Set(leaves.value.map(l=>l.employee))].sort());
const away=(name,date)=>leaves.value.some(l=>l.employee===name&&l.start<=date&&l.end>=date);
const subsets=key=>(props.records[key]||[]).filter(x=>!x.employee||names.value.has(x.employee));
const group=(list,field)=>Object.entries(list.reduce((a,r)=>{const k=String(r[field]||'Unspecified');a[k]=(a[k]||0)+1;return a;},{})).sort((a,b)=>b[1]-a[1]);
const byDepartment=computed(()=>departments.value.map(d=>({...d,people:staff.value.filter(e=>String(e.departmentId||e.department||'')===String(d.id))})).filter(x=>x.people.length));
const unmanaged=computed(()=>staff.value.filter(e=>!byDepartment.value.some(d=>d.people.includes(e))));
const claims=computed(()=>subsets('claims'));
const claimCategories=computed(()=>group(claims.value,'category').map(([name,count])=>({name,count,amount:claims.value.filter(c=>String(c.category||'Unspecified')===name).reduce((s,x)=>s+(Number(x.amount)||0),0)})));
const recruitment=computed(()=>group(subsets('recruitment'),'stage'));
const training=computed(()=>subsets('training'));
const upcomingTraining=computed(()=>training.value.filter(t=>t.expiry&&t.expiry>=new Date().toISOString().slice(0,10)).sort((a,b)=>a.expiry.localeCompare(b.expiry)).slice(0,12));
const appraisals=computed(()=>subsets('appraisals'));
const ratings=computed(()=>appraisals.value.filter(r=>Number.isFinite(Number(r.finalRating))&&Number(r.finalRating)>0).map(r=>({...r,rating:Number(r.finalRating)})));
const mean=computed(()=>ratings.value.length?(ratings.value.reduce((s,r)=>s+r.rating,0)/ratings.value.length).toFixed(2):'—');
const amt=n=>Number(n||0).toLocaleString('en-MY',{style:'currency',currency:'MYR'});
const percent=(v,max)=>`${Math.max(0,Math.min(100,max?v/max*100:0))}%`;
const maxCount=rows=>Math.max(1,...rows.map(r=>r[1]));
const csvCell=x=>'"'+String(x??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';
function download(name,table){const csv='\uFEFF'+table.map(row=>row.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`PplosHR-${name}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function windowPrint(){window.print();}
function exportCurrent(){if(tab.value==='organization')download('Organization',[['Department','Employee','Job title','Reporting manager'],...byDepartment.value.flatMap(d=>d.people.map(e=>[d.title,e.name,e.jobTitle||'',e.manager||''])),...unmanaged.value.map(e=>['Unassigned',e.name,e.jobTitle||'',e.manager||''])]);
else if(tab.value==='leave')download('Team-Leave',[['Employee','Leave type','Start','End'],...leaves.value.map(l=>[l.employee,l.type,l.start,l.end])]);
else if(tab.value==='claims')download('Claims-Summary',[['Category','Claims count','Amount RM'],...claimCategories.value.map(x=>[x.name,x.count,x.amount])]);
else if(tab.value==='recruitment')download('Recruitment-Funnel',[['Stage','Candidates'],...recruitment.value]);
else if(tab.value==='training')download('Training-Expiry',[['Employee','Course','Certificate expiry'],...upcomingTraining.value.map(x=>[x.employee,x.title,x.expiry])]);
else download('Appraisal-Summary',[['Employee','Final rating'],...ratings.value.map(x=>[x.employee,x.rating])]);}
</script>
<template>
<section v-if="allowed" class="hi-workspace" aria-label="HR management insights">
 <header class="hi-header"><div><h5>Management insights</h5><p>Live summaries of authorized records. Read-only; approvals and edits remain in existing HR screens.</p></div><div class="hi-controls"><button type="button" @click="exportCurrent">Export CSV</button><button type="button" @click="windowPrint">Print / Save PDF</button></div></header>
 <div class="hi-filters"><label>Company <select v-model="company" @change="department='all'"><option value="all">All permitted companies</option><option v-for="c in companies" :key="c.id" :value="String(c.id)">{{c.title}}</option></select></label><label>Department <select v-model="department"><option value="all">All departments</option><option v-for="d in departments" :key="d.id" :value="String(d.id)">{{d.title}}</option></select></label><label>Leave month <input v-model="month" type="month" /></label></div>
 <nav class="hi-tabs" aria-label="Insights sections"><button v-for="t in [{id:'organization',name:'Organization'},{id:'leave',name:'Team Leave'},{id:'claims',name:'Claims'},{id:'recruitment',name:'Recruitment'},{id:'training',name:'Training'},{id:'appraisal',name:'Performance'}]" :key="t.id" type="button" :aria-pressed="tab===t.id" @click="tab=t.id">{{t.name}}</button></nav>
 <div v-if="tab==='organization'" class="hi-content"><h6>Organization & reporting structure</h6><p>Department groupings use saved employee department assignments. Reporting manager is shown as recorded; unassigned staff remain visible.</p><div v-for="d in byDepartment" :key="d.id" class="hi-department"><strong>{{d.title}} <small>({{d.people.length}})</small></strong><p>Department head: {{d.manager||'Not set'}}</p><div class="hi-tags"><span v-for="e in d.people" :key="e.name" :title="'Reports to '+(e.manager||'Not set')">{{e.name}} <small>· {{e.jobTitle||'Title not assigned'}}</small></span></div></div><div v-if="unmanaged.length" class="hi-department"><strong>Unassigned ({{unmanaged.length}})</strong><div class="hi-tags"><span v-for="e in unmanaged" :key="e.name">{{e.name}}</span></div></div><p v-if="!staff.length" class="hi-empty">No visible employee records.</p></div>
 <div v-else-if="tab==='leave'" class="hi-content"><h6>Approved team leave · {{month}}</h6><p>Highlights recorded leave overlap. A staffing minimum cannot be inferred without a department staffing policy.</p><div class="hi-scroll"><table><thead><tr><th>Employee</th><th v-for="d in days" :key="d">{{Number(d.slice(-2))}}</th></tr></thead><tbody><tr v-for="name in namesOfLeaves" :key="name"><th>{{name}}</th><td v-for="d in days" :key="d" :class="{'hi-away':away(name,d)}" :title="away(name,d)?name+' on leave '+d:d">{{away(name,d)?'●':''}}</td></tr></tbody></table></div><p v-if="!namesOfLeaves.length" class="hi-empty">No approved team leave found for the selected month.</p></div>
 <div v-else-if="tab==='claims'" class="hi-content"><h6>Claims by category</h6><p>Amounts are requested claim amounts, not necessarily paid reimbursements or payroll expenses.</p><div v-for="x in claimCategories" :key="x.name" class="hi-bar"><span>{{x.name}}</span><div class="hi-track"><i :style="{width:percent(x.count,Math.max(1,...claimCategories.map(y=>y.count)))}"></i></div><b>{{x.count}} · {{amt(x.amount)}}</b></div><p v-if="!claimCategories.length" class="hi-empty">No claim records in the authorized scope.</p></div>
 <div v-else-if="tab==='recruitment'" class="hi-content"><h6>Recruitment pipeline</h6><p>Candidate counts by current stage; this is not a historical conversion rate.</p><div v-for="[name,count] in recruitment" :key="name" class="hi-bar"><span>{{name}}</span><div class="hi-track"><i :style="{width:percent(count,maxCount(recruitment))}"></i></div><b>{{count}}</b></div><p v-if="!recruitment.length" class="hi-empty">No candidate records.</p></div>
 <div v-else-if="tab==='training'" class="hi-content"><h6>Training and certification register</h6><p>Upcoming expiry dates across visible, recorded certificates.</p><div class="hi-stats"><span>Records: <b>{{training.length}}</b></span><span>With future expiry: <b>{{upcomingTraining.length}}</b> <small>(first 12)</small></span></div><div v-for="x in upcomingTraining" :key="x.id" class="hi-line"><b>{{x.employee}}</b><span>{{x.title}}</span><time>{{x.expiry}}</time></div><p v-if="!upcomingTraining.length" class="hi-empty">No future certificate expiry dates recorded.</p></div>
 <div v-else class="hi-content"><h6>Appraisal final ratings</h6><p>Shows finalized ratings only. Missing ratings are excluded from the average.</p><div class="hi-stats"><span>Appraisal records: <b>{{appraisals.length}}</b></span><span>Final ratings: <b>{{ratings.length}}</b></span><span>Mean final rating: <b>{{mean}}</b></span></div><div v-for="r in ratings" :key="r.id" class="hi-bar"><span>{{r.employee}}</span><div class="hi-track"><i :style="{width:percent(r.rating,5)}"></i></div><b>{{r.rating}} / 5</b></div><p v-if="!ratings.length" class="hi-empty">No recorded final ratings.</p></div>
</section>
</template>
<style scoped>
.hi-workspace{background:#fff;border:1px solid #e3e8ed;border-radius:16px;padding:22px;margin:16px 0;font-size:14px;color:#243242}.hi-header{display:flex;justify-content:space-between;gap:20px;align-items:start;flex-wrap:wrap}.hi-header h5{margin:0 0 6px}.hi-header p,.hi-content>p{color:#657383;font-size:13px}.hi-controls,.hi-filters,.hi-tabs{display:flex;flex-wrap:wrap;gap:9px}.hi-controls button,.hi-tabs button{border:1px solid #dbe2e9;border-radius:8px;background:#fff;padding:7px 11px;color:#304761}.hi-tabs button[aria-pressed=true]{background:#eaf0f6;border-color:#809bb4;font-weight:650}.hi-filters{margin:16px 0}.hi-filters label{font-size:12px;color:#627184}.hi-filters select,.hi-filters input{display:block;border:1px solid #d3dce5;border-radius:7px;padding:7px;max-width:220px}.hi-tabs{border-bottom:1px solid #dce3ea;padding-bottom:12px}.hi-content{padding-top:18px}.hi-content h6{font-weight:700}.hi-department{border-left:3px solid #7998b3;margin:10px 0;padding:10px 14px;background:#f7f9fb}.hi-department p{margin:5px 0;color:#687785}.hi-tags{display:flex;gap:7px;flex-wrap:wrap}.hi-tags span{background:white;border:1px solid #e2e7ec;border-radius:8px;padding:7px}.hi-tags small{color:#748496}.hi-scroll{max-width:100%;overflow:auto}.hi-scroll table{border-collapse:collapse;white-space:nowrap}.hi-scroll th,.hi-scroll td{border:1px solid #e7ebf0;text-align:center;min-width:23px;padding:5px}.hi-scroll th:first-child{position:sticky;left:0;background:#fff;min-width:150px;text-align:left}.hi-away{background:#b9d3df;color:#2f647a}.hi-bar{display:grid;grid-template-columns:130px minmax(70px,1fr) auto;gap:12px;align-items:center;padding:9px 0}.hi-track{height:9px;background:#e9edf2;border-radius:10px;overflow:hidden}.hi-track i{height:100%;background:#6689a7;display:block;border-radius:10px}.hi-bar b{font-size:12px}.hi-stats{display:flex;gap:18px;flex-wrap:wrap;margin:15px 0}.hi-stats span{padding:11px;background:#f3f6f8;border-radius:8px}.hi-line{display:grid;grid-template-columns:1fr 2fr auto;gap:10px;border-bottom:1px solid #e5ebf0;padding:9px}.hi-empty{padding:14px;background:#f6f8fa;border-radius:8px}@media(max-width:650px){.hi-workspace{padding:12px}.hi-bar{grid-template-columns:100px minmax(40px,1fr);gap:5px}.hi-bar b{grid-column:2}.hi-line{grid-template-columns:1fr}.hi-tabs button{font-size:12px}}@media print{.hi-controls,.hi-filters,.hi-tabs{display:none}.hi-workspace{border:0}.hi-scroll{overflow:visible}}
</style>
